const request = $('Webhook').first().json.body || {};

const version = $('Get Approved Scope Version').first().json;

const rows = $input.all()
  .map(item => item.json)
  .filter(item => item.id && item.category);

if (!version?.id || version.status !== 'approved') {
  throw new Error('No approved scope version found.');
}

const grouped = {
  deliverables: [],
  included_services: [],
  excluded_services: [],
  client_responsibilities: [],
  unresolved_items: []
};

for (const item of rows) {
  const entry = {
    title: item.title || '',
    description: item.description || null
  };

  switch (item.category) {
    case 'deliverable':
      grouped.deliverables.push(entry);
      break;
    case 'included':
      grouped.included_services.push(entry);
      break;
    case 'excluded':
      grouped.excluded_services.push(entry);
      break;
    case 'client_responsibility':
      grouped.client_responsibilities.push(entry);
      break;
    case 'unresolved':
      grouped.unresolved_items.push(entry);
      break;
  }
}

// Prefer scope_items when populated.
// Otherwise, use the structured JSONB fields.
const approvedScope = {
  id: version.id,
  project_id: version.project_id,
  user_id: version.user_id,
  version_number: version.version_number,
  status: version.status,

  scope_title: version.scope_title,
  summary: version.summary,

  deliverables:
    grouped.deliverables.length
      ? grouped.deliverables
      : (version.deliverables || []),

  included_services:
    grouped.included_services.length
      ? grouped.included_services
      : (version.included_services || []),

  excluded_services:
    grouped.excluded_services.length
      ? grouped.excluded_services
      : (version.excluded_services || []),

  client_responsibilities:
    grouped.client_responsibilities.length
      ? grouped.client_responsibilities
      : (version.client_responsibilities || []),

  unresolved_items: grouped.unresolved_items,

  revision_rounds: version.revision_rounds,
  delivery_deadline: version.delivery_deadline,
  delivery_condition: version.delivery_condition,
  terms: version.terms
};

return [{
  json: {
    body: {
      ...request,
      approved_scope: approvedScope
    }
  }
}];

const response = $input.first().json;

const content = response?.candidates?.[0]
  ?.content?.parts
  ?.map(part => part.text || "")
  .join("")
  .trim();

if (!content) {
  return [{
    json: {
      success: false,
      error: "Gemini لم يرجع نتيجة نصية"
    }
  }];
}

let analysis;

try {
  const cleaned = content
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/, "")
    .replace(/,\s*([}\]])/g, "$1");

  analysis = JSON.parse(cleaned);
} catch (error) {
  return [{
    json: {
      success: false,
      error: "تعذر قراءة JSON من Gemini",
      details: error.message
    }
  }];
}

// Retrieve the actual approved agreement
const webhookBody = $('Webhook').first().json.body || {};

const scope = webhookBody.approved_scope;

if (!scope || scope.status !== "approved") {
  throw new Error("No valid approved scope found.");
}

const allowed = [
  "within_scope",
  "additional_work",
  "needs_clarification"
];

// Only approved contractual fields count as evidence
const approvedText = JSON.stringify({
  deliverables: scope.deliverables || [],
  included_services: scope.included_services || [],
  excluded_services: scope.excluded_services || [],
  client_responsibilities: scope.client_responsibilities || [],
  terms: scope.terms || "",
  summary: scope.summary || ""
});

// Never use unresolved items as evidence
const hasApprovedDuration =
  /(?:\d+)\s*(?:ثانية|ثوانٍ|ثواني|دقيقة|دقائق|ساعة|ساعات|seconds?|secs?|minutes?|mins?|hours?)/i
  .test(approvedText);

const hasApprovedConceptChangeRule =
  /(?:تغيير|تعديل).{0,30}(?:الفكرة|المفهوم)|(?:الفكرة|المفهوم).{0,30}(?:إضافي|مستثنى|خارج النطاق)/i
  .test(approvedText);

const assessment = Array.isArray(analysis.change_assessment)
  ? analysis.change_assessment.map(item => {

      let classification = allowed.includes(item.classification)
        ? item.classification
        : "needs_clarification";

      let evidence = item.agreement_evidence || "";
      let reason = item.reason || "";
      let action = item.recommended_action || "";

      const requested = item.requested_change || "";

      // Duration must have an explicit approved baseline
      if (
        /مدة|ثانية|دقيقة/.test(requested) &&
        !hasApprovedDuration
      ) {
        classification = "needs_clarification";
        evidence = "لا يوجد بند معتمد وصريح يحسم مدة الفيديو.";
        reason = "المدة الأصلية وردت ضمن البنود غير المحسومة، ولا يجوز اعتبارها مدة تعاقدية معتمدة.";
        action = "مراجعة وتأكيد المدة الأصلية مع المستقل قبل تحديد أثر الزيادة.";
      }

      // Conceptual change requires an explicit approved clause
      if (
        /تغيير.*(?:الفكرة|المفهوم)|(?:الفكرة|المفهوم).*بالكامل/.test(requested) &&
        !hasApprovedConceptChangeRule
      ) {
        classification = "needs_clarification";
        evidence = "لا يوجد بند معتمد وصريح يحسم تغيير الفكرة.";
        reason = "الاتفاق لا يتضمن شرطاً واضحاً يحدد سياسة تغيير الفكرة بعد اعتمادها.";
        action = "توضيح حجم التغيير المطلوب ومراجعته مع المستقل.";
      }

      return {
        requested_change: requested,
        classification,
        agreement_evidence: evidence,
        reason,
        potential_impact: item.potential_impact || "",
        recommended_action: action
      };
    })
  : [];

// Determine overall classification from validated items
const hasAdditional = assessment.some(
  item => item.classification === "additional_work"
);

const hasClarification = assessment.some(
  item => item.classification === "needs_clarification"
);

const overall = hasAdditional
  ? "additional_work"
  : hasClarification
    ? "needs_clarification"
    : "within_scope";

const additionalItems = assessment
  .filter(item => item.classification === "additional_work");

const clarificationItems = assessment
  .filter(item => item.classification === "needs_clarification");

// Generate a response consistent with validated findings
let suggestedResponse = "مرحباً، شكراً لتوضيح طلباتك. ";

if (additionalItems.length) {
  suggestedResponse +=
    "بعد مراجعة الاتفاق المعتمد، تبيّن أن الطلبات التالية تمثل أعمالاً إضافية: " +
    additionalItems.map(item => item.requested_change).join("، ") +
    ". يمكننا مناقشة تفاصيلها وتحديث الاتفاق بعد موافقتك. ";
}

if (clarificationItems.length) {
  suggestedResponse +=
    "كما توجد نقاط تحتاج إلى توضيح قبل تحديد نطاقها النهائي: " +
    clarificationItems.map(item => item.requested_change).join("، ") +
    ". نرجو توضيحها حتى نتمكن من تحديد المتطلبات بدقة.";
}

if (!additionalItems.length && !clarificationItems.length) {
  suggestedResponse +=
    "الطلبات الجديدة تقع ضمن نطاق الاتفاق المعتمد.";
}

return [{
  json: {
    success: true,
    model: response.modelVersion || "Gemini Flash",
    analysis: {
      overall_classification: overall,
      change_summary: analysis.change_summary || "",
      change_assessment: assessment,
      unchanged_items: analysis.unchanged_items || [],
      missing_information: analysis.missing_information || [],
      risks: analysis.risks || [],
      suggested_questions: analysis.suggested_questions || [],
      suggested_response: suggestedResponse,
      requires_scope_update: hasAdditional,
      scope_update_reason: hasAdditional
        ? "توجد أعمال إضافية مؤكدة: " +
          additionalItems.map(item => item.requested_change).join("، ")
        : ""
    }
  }
}];
